import{_ as e,c as p,o as r,af as h}from"./chunks/framework.BKeRpnBD.js";const b=JSON.parse('{"title":"恒","description":"高岛易断 - 恒","frontmatter":{"title":"恒","description":"高岛易断 - 恒"},"headers":[],"relativePath":"zh/classics/takashima/032.md","filePath":"zh/classics/takashima/032.md"}'),i={name:"zh/classics/takashima/032.md"};function l(n,a,d,t,s,c){return r(),p("div",null,[...a[0]||(a[0]=[h('<h1 id="恒" tabindex="-1">恒 <a class="header-anchor" href="#恒" aria-label="Permalink to “恒”">​</a></h1><h2 id="恒-1" tabindex="-1">恒 <a class="header-anchor" href="#恒-1" aria-label="Permalink to “恒”">​</a></h2><h2 id="卦辞" tabindex="-1">卦辞 <a class="header-anchor" href="#卦辞" aria-label="Permalink to “卦辞”">​</a></h2><p>恒：亨，无咎，利贞。利有攸往。</p><h2 id="卦辞注" tabindex="-1">卦辞注 <a class="header-anchor" href="#卦辞注" aria-label="Permalink to “卦辞注”">​</a></h2><p>“恒”字，从心从亘，训常，《易》曰“恒，久也”，凡事暂时塞者，久则通，通则“无咎”。“贞”者，正也，《咸》为夫妇结缡之始，男下于女，故“娶女吉”；《恒》为夫妇居室之常，女下于男，故利其贞。《巽》柔而顺，顺故能贞；《震》刚而动，动故有往。“贞”者，女子之德也，“往”者，男子之事也。《正义》曰：“得其常道，何往不利？”故曰“利有攸往”也。</p><h2 id="象辞" tabindex="-1">象辞 <a class="header-anchor" href="#象辞" aria-label="Permalink to “象辞”">​</a></h2><p>雷风，恒，君子以立不易方。</p><h2 id="象辞注" tabindex="-1">象辞注 <a class="header-anchor" href="#象辞注" aria-label="Permalink to “象辞注”">​</a></h2><p>《震》雷动而在上，《巽》风入而在下，雷风二物，虽至动至变而无常，而究其极，雷之发声不爽其候，风之嘘物，各应其时，振古如斯，未尝或失，故曰雷风《恒》。君子体此象以应万变，而道则不变，《恒》而已矣。“立”者确乎不拔，“方”者主一不迁，志有定向，而持守弥坚，不为富贵淫，不为贫贱移，不为威武屈，特立无惧，此君子之所以为君子者，得《恒》道也。</p><h2 id="占断" tabindex="-1">占断 <a class="header-anchor" href="#占断" aria-label="Permalink to “占断”">​</a></h2><p>○　问战征：雷出于地，风生于谷，防有敌兵埋伏，火炮攻击之虑。宜坚守营垒，不可退，后可以转败为功。</p><p>○　问营商：《震》属正东，《巽》属东南，曰“立不易方”，言贸易不可改易地方也。</p><p>○　问功名：《震》《巽》皆木，木植立不易，干霄直上，自得直达之象。但宜久成，不宜躁进。</p><p>○　问家宅：此宅坐西北，朝东南，为祖遗旧宅，是恒产，方向切不可移易。</p><p>○　问婚姻：男家长男，女家长女，二长相配，婚姻大利，可卜百年偕老。</p><p>○　问疾病：必是肝火上冲，痰火气喘，须服前方，不必改易。</p><p>○　问六甲：生男，必是初胎。</p><h2 id="初六解" tabindex="-1">初六解 <a class="header-anchor" href="#初六解" aria-label="Permalink to “初六解”">​</a></h2><p>“浚”，深也。初爻当《恒》之始，以始求终，所当循序渐进，方能几及，所谓登高必自卑，行远必自迩，由此以往，无不利也。若乃辍等以求，如撮土而期为山，勺水而欲成海，初基乍立，后效殊奢，事虽不失其正，要必难免于凶也，故曰“浚恒，贞凶”。《象传》曰“始求深也”，“始”，指初爻也，谓其未涉其浅，而遽求其深，是欲速而不达者也，非徒无益，反见其凶，譬如用智而失之凿，求道而索之隐，皆“浚恒”者之过也。</p><h2 id="初六占" tabindex="-1">初六占 <a class="header-anchor" href="#初六占" aria-label="Permalink to “初六占”">​</a></h2><p>○　问战征：宜步步为营，切忌孤军深入，深入必凶。</p><p>○　问营商：宜得利即售，不可垄断居奇，以贪高价。</p><p>○　问功名：宜安分守职，切勿梯宠希荣，徼幸图功，恐反招辱。</p><p>○　问婚姻：婚姻之道，宜以门户相当，切勿慕富攀贵，贪结亲，反致后悔。往往有之。</p><p>○　问家宅：宅是新建，惜乎过求华丽，致难持久。</p><p>○　问讼事：恐一经涉讼，历久不了。</p><p>○　问六甲：初胎，生女，惟恐难育。</p><h2 id="初六案例" tabindex="-1">初六案例 <a class="header-anchor" href="#初六案例" aria-label="Permalink to “初六案例”">​</a></h2><p>明治十五年七月，朝鲜变起，花房公使以下，脱归长崎，同年八月，朝廷发陆海军，命花房公使重至朝鲜，使之问罪。余筮之，得《恒》之《大壮》。</p><p>断曰：《观》初六爻辞，知朝鲜之渐进开化也。今番朝鲜虽失礼于我，若政府乘一朝之怒，忘恒久之道，责之过深，则是爻辞所云“浚恒，贞凶，无攸利”，正当为政府虑矣。问政府今用问罪之举，不在深求，而在和解，则其事可谐，即或一时未谐，《恒》之初爻，变为《大壮》，则以《大壮》之军备，压制而已。其策则分我军为六，留其四于马关，以其二为朝鲜开化党之声援；如此而犹有不及，可使一军自元山津而冲其背，可使开化党维持朝鲜也，是天数之理也。筮毕，呈之某贵显，贵显又使人更问曰：朝鲜之事，虽不足忧，清国之关系实大也，子幸占我国与清国关系。余复筮之，得《艮》之不变。断曰：《艮》者两山相对之卦，两山相对，可见而不可近也，又不可相应也。于不近不应之卦，其无战争，断可知也。其后朝鲜之事，果如此占。</p><h2 id="九二解" tabindex="-1">九二解 <a class="header-anchor" href="#九二解" aria-label="Permalink to “九二解”">​</a></h2><p>二爻以阳居阴，是失位也，失位故有悔；然二处《巽》之中，为《巽》之主，二与六五阴阳相应，以刚中之德，辅柔中之君，道既得中，又能持久，故曰“悔亡”。《象传》曰“能久中也”，谓可久之道，不外乎中，能“久于其道”，必能久于其中也。二爻能之，悔自亡矣。</p><h2 id="九二占" tabindex="-1">九二占 <a class="header-anchor" href="#九二占" aria-label="Permalink to “九二占”">​</a></h2><p>○　问战征：营位失当，恐有后悔，惟宜居中不动，持久固守，可免祸也。</p><p>○　问营商：货物不得销路，致有耗败，宜历久待价，可得反本。</p><p>○　问功名：失其机会，反招灾害，待时而往，虽不成名，亦无尤也。</p><p>○　问家宅：此宅地位不当，居者不利。十年之后，宅运可转，方得无咎。</p><p>○　问婚姻：平平。</p><p>○　问六甲：女生。</p><h2 id="九二案例" tabindex="-1">九二案例 <a class="header-anchor" href="#九二案例" aria-label="Permalink to “九二案例”">​</a></h2><p>某会社社长，来请占社运，筮得《恒》之《小过》。</p><p>断曰：此卦“雷风相与”，“刚柔皆应”，是会社之象也。卦名曰《恒》，业必以久而成也。今占得第二爻，二爻以阳居阴，未免位置不当，事有窒碍；足下躬膺社长，当以中正处之，保其恒久。守《巽》之贞，法《震》之往，历久不倦，而推行尽利，其道乃亨，何悔之有？社长闻之曰：该社自开业以来，多不能如意，今得此占，自当恒久不已，以图远大之业。后此会社，果得盛大。</p><p>明治二十六年二月，北海道炭矿铁道会社支配人植村登三郎来曰：余从事社务有年，事务多端，深恐力弱才微，不胜其任，思欲改就官职，犹豫未决，幸请一筮。筮得《恒》之《小过》。</p><p>断曰：《巽》下《震》上，《巽》为薪，有煤炭之象，《巽》又为商，为利，有会社之象；《震》为行、为奔，有铁道之象。今占得第二爻，九二《坎》爻，辰在子，上值虚，虚为北方列宿之中，故会社在北海道。二爻以阳居阴，为失位，故有悔，然足下既从事社务，必深识其中之利益，久于其道，自然精明练达，能振兴其业也。后植村氏得此占，益加勉励，不数月，至占重任。</p><h2 id="九三解" tabindex="-1">九三解 <a class="header-anchor" href="#九三解" aria-label="Permalink to “九三解”">​</a></h2><p>九三处《巽》之极，《巽》为进退，为不果，“不恒其德”之象。“羞”者，耻也，九三以阳居阳，其位虽正，因其执心不定，德性无恒，而错误随之。“或”者，将然之辞，谓虽未明见其羞，而羞或承之矣，虽贞亦吝。“吝”谓可鄙也，《象传》曰“无所容也”，大节一亏，无所逃于天地之间，盖深斥之也。</p><h2 id="九三占" tabindex="-1">九三占 <a class="header-anchor" href="#九三占" aria-label="Permalink to “九三占”">​</a></h2><p>○　问战征：军事贵勇往果决，得以制胜，《巽》为不果，必多畏却，则进退无恒，势将辱国伤师，咎何能辞？</p><p>○　问营商：爻辞曰“不恒其德”，是必商无恒业也，何以获利？</p><p>○　问功名：二三其德，业必不就，名何由成？</p><p>○　问家宅：三爻居《巽》之终，《巽》终变《震》，《震》为大途，此宅必近大道之旁，其宅不利久居。</p><p>○　问婚姻：姻事不终，恐贻羞辱。</p><p>○　问六甲：生女。</p><h2 id="九三案例" tabindex="-1">九三案例 <a class="header-anchor" href="#九三案例" aria-label="Permalink to “九三案例”">​</a></h2><p>一日某贵显来访，谓余曰：有同僚某，因负债请余援助，长官某亦代为说合，予诺之，而后至期，彼竟无力得尝，敢请占其得失。筮得《恒》之《解》。</p><p>断曰：此卦“恒久而不已”，是其贷与，永不返还可知。其辞曰“不恒其德”，谓彼穷迫如此，势必二三其德，不能《恒》守此约信也。“或承之羞”，谓君若盛气责之，彼必出言不逊，反受羞辱也。后果如此占。</p><p>明治二十八年，占清国国运，筮得《恒》之《解》。</p><p>断曰：《恒》者，久也，溯我国与外国交际，惟清国最旧，是《恒》之象也。两国并立亚细亚，辅车相依，同文之国，尤最亲密。近年欧美各邦，文明开化，日新一日，我国有所见于此，是以取彼之长，补我之短，乃遣少年子弟留学欧西，又聘西国教师，使之教我子弟。在清国墨守旧习，自示尊大，不能达观宇内大势。朝鲜介我两国之间，我与清国商议，谋欲互为保护，清国有疑于我，终至兵阵相见。今占得三爻，爻辞曰“不恒其德，或承之羞，贞吝”，《巽》为进退，谓清国进退无恒，势必辱也。</p><h2 id="九四解" tabindex="-1">九四解 <a class="header-anchor" href="#九四解" aria-label="Permalink to “九四解”">​</a></h2><p>“禽”者，鸟兽之总名，《震》为猎夫，《巽》为禽。九四处《震》之初，已出于《巽》，是《震》之猎夫前进，《巽》之禽后退，以此而田，必无获也，故曰“田无禽”，以喻失民心也。夫所贵于《恒》之道者，德称其位，才胜其任，事上而有所建明，治下而有所康济，积日累久，则其所裨益必多。九四以阳居阳，与初六相应，初六“浚恒”既“无攸利”，无利者，亦即“无禽”之谓也。《象传》曰“久非其位，安得禽也”，大凡所处非其地，所乘非其时，所为非其方，所交非其人，皆久而无功也。田之于禽，其得失最著者也，故以之为象。</p><h2 id="九四占" tabindex="-1">九四占 <a class="header-anchor" href="#九四占" aria-label="Permalink to “九四占”">​</a></h2><p>○　问战征：立营不得其位，必致师老无功。</p><p>○　问营商：凡货物销售，各有其地，如求木于渔，问鱼于樵，虽久于其业，必无获也。</p><p>○　问功名：如不入场屋，而望高科，不登廊庙，而求显官，居非其位，虽久无获也。</p><p>○　问家宅：此宅方位不利，不可久居，宜急迁移。</p><p>○　问婚姻：两姓配偶不合。</p><p>○　问六甲：生男，恐难养育。</p><h2 id="九四案例" tabindex="-1">九四案例 <a class="header-anchor" href="#九四案例" aria-label="Permalink to “九四案例”">​</a></h2><p>明治二十三年，某缙绅来，请占某贵显气运，筮得《恒》之《升》。</p><p>断曰：就卦论卦，直言不讳，望勿见责。今君为某贵显占气运，得《恒》之四爻，四爻以阳居阴，居不当位，爻辞曰“田无禽”，犹言谋而无功也。知某贵显虽久处高位，目下时运已退，才力亦衰，凡所作为，多无成效，自宜退隐，毋贻窃位之讥也。</p><h2 id="六五解" tabindex="-1">六五解 <a class="header-anchor" href="#六五解" aria-label="Permalink to “六五解”">​</a></h2><p>六五居得尊位，为《恒》之主，下与九二相应。九二居《巽》，《巽》为妇，六五居《震》，《震》为夫。六五专守九二之应，贞一其德，贞则贞矣，为妇则吉，为夫凶也。不知五为《震》主，《震》为行，丈夫之志，当以义制事，推行尽利，以垂久之业，若第以从一为正，是妾妇之道也，孟子所谓“贱丈夫”者是也。《象传》曰“从一而终”，谓妇人之德，惟宜从一，故曰“贞吉”；夫“夫子制义”，谓丈夫之行，惟宜审义。义则不害于贞，贞则或伤其义，故曰“从妇凶也”。《象传》所云“贞吉”者，指妇人也；“利有攸往”者，指丈夫也。知夫此，而《恒》之道得矣。</p><h2 id="六五占" tabindex="-1">六五占 <a class="header-anchor" href="#六五占" aria-label="Permalink to “六五占”">​</a></h2><p>○　问战征：古称军中有妇女，士气不扬，项羽之败，未始非虞姬累之也。行军宜凛之。</p><p>○　问营商：商业宜随时变通，若拘泥执一，妇孺贪小之见，必无大利也。</p><p>○　问功名：丈夫志在四方，前程远大，若徒贪恋闺房，伤身败名，凶莫大焉。</p><p>○　问家宅：古云“牝鸡司晨，惟家之索”，是当深戒。</p><p>○　问婚姻：女家占此则吉，男家占此则凶。</p><p>○　问六甲：生男。</p><h2 id="六五案例" tabindex="-1">六五案例 <a class="header-anchor" href="#六五案例" aria-label="Permalink to “六五案例”">​</a></h2><p>豪商某来，请占气运，筮得《恒》之《大过》。</p><p>断曰：足下久营商业，精明强干，余所素知。今占气运，得《恒》之五爻，五为《震》之主爻，《震》为从，故《象》曰“从妇凶”。夫女子小人，皆属阴象，商业之推行，权宜自主，不可听从人言，治家之道，亦不可偏听妇言。爻象之辞，垂诫深矣，足下宜凛之！</p><h2 id="上六解" tabindex="-1">上六解 <a class="header-anchor" href="#上六解" aria-label="Permalink to “上六解”">​</a></h2><p>《震》动也，故《恒》至于上，有振动之象焉。上六处《震》之终，为动之极。动者宜守之以静，终者宜返之以始，斯德可全于末路，业不败于垂成，恒道成矣。今上六处《恒》之极，而振动不已，以振为恒，恒有尽而振无尽，是以凶也。《震》为决躁，《巽》亦为躁卦，躁动无时，犹是雷发而不收，风行而不止，其何能有功哉！故《象传》曰“大无功也”。</p><h2 id="上六占" tabindex="-1">上六占 <a class="header-anchor" href="#上六占" aria-label="Permalink to “上六占”">​</a></h2><p>○　问战征：上为主帅，行军之道，全在镇定，若妄动喜功，必无成也。</p><p>○　问营商：上为一卦之归宿，是商业归结之时也，当归结而不归，收发无时：终无结局也。</p><p>○　问功名：上处卦之终，功名已尽，若复痴心妄求，不特无成，恐反致祸。</p><p>○　问家宅：此宅已旧，不必改作，改作必凶。</p><p>○　问婚姻：必是晚年续娶也。无须再娶，娶则必凶。</p><p>○　问讼事：急宜罢讼。</p><p>○　问失物：不得。</p><h2 id="上六案例" tabindex="-1">上六案例 <a class="header-anchor" href="#上六案例" aria-label="Permalink to “上六案例”">​</a></h2><p>某商人来，请占气运，筮得《恒》之《鼎》。</p><p>断曰：凡占卦遇上爻，上为卦之终局，必其人好运已终，只宜静守而已。今《恒》之上六，曰“振恒”，以振为恒，是卦已终，而动未终，故曰凶也。足下占得此爻，当守静以制动，斯可无咎。</p>',96)])])}const m=e(i,[["render",l]]);export{b as __pageData,m as default};
